'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fetchData=async name=>{const r=await fetch(`/data/${name}.json`);if(!r.ok)throw new Error(`Unable to load ${name}. Please reload.`);return r.json()};
let toastTimer;function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000)}
const storageKey='united-piping-enquiry-v1';
let items=[];try{const stored=JSON.parse(localStorage.getItem(storageKey)||'[]');if(Array.isArray(stored))items=stored.filter(x=>x&&typeof x.id==='string'&&typeof x.uid==='string').slice(0,100)}catch{toast('Browser storage is unavailable. Your enquiry will last for this page only.')}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(items))}catch{toast('Unable to save in this browser. Download your draft before leaving.')}updateCount()}
function updateCount(){$$('[data-count]').forEach(e=>e.textContent=items.length)}updateCount();
function addProduct(id,notes=''){if(items.length>=100){toast('The enquiry supports up to 100 lines.');return}items.push({uid:crypto.randomUUID?crypto.randomUUID():String(Date.now()+Math.random()),id,material:'',grade:'',standard:'',size:'',quantity:'',notes});persist();toast('Product added to your enquiry.');if($('#rfq-items'))renderItems()}
const menuButton=$('.menu-toggle'),nav=$('#main-nav');
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',open);nav.classList.toggle('open',open)});
function closeMenus(){ $$('.nav-trigger').forEach(b=>b.setAttribute('aria-expanded','false'));$$('.mega-menu').forEach(e=>e.classList.remove('open'))}
$$('.nav-trigger').forEach(b=>b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')!=='true';closeMenus();b.setAttribute('aria-expanded',open);$('#'+b.getAttribute('aria-controls')).classList.toggle('open',open)}));
document.addEventListener('click',e=>{if(!e.target.closest('.site-header'))closeMenus();const add=e.target.closest('.add-product');if(add)addProduct(add.dataset.id,add.dataset.notes||'')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const active=$('.nav-trigger[aria-expanded=true]');closeMenus();if(active)active.focus();if(nav.classList.contains('open')){nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.focus()}}});
function tabs(container,callback){const btns=$$('[role=tab]',container);btns.forEach((b,i)=>{b.addEventListener('click',()=>{btns.forEach(x=>{x.setAttribute('aria-selected',x===b);x.tabIndex=x===b?0:-1});callback(i)});b.addEventListener('keydown',e=>{let target;if(['ArrowRight','ArrowDown'].includes(e.key))target=(i+1)%btns.length;if(['ArrowLeft','ArrowUp'].includes(e.key))target=(i-1+btns.length)%btns.length;if(e.key==='Home')target=0;if(e.key==='End')target=btns.length-1;if(target!==undefined){e.preventDefault();btns[target].focus();btns[target].click()}})})}
let productData=[];
async function initProducts(){productData=await fetchData('products');const tabsEl=$('.product-tabs');if(tabsEl){tabs(tabsEl,i=>window.renderProductExplorer(productData[i],i));window.renderProductExplorer(productData[0],0)};if($('#rfq-items'))renderItems();if($('#valve-results'))initValves()}
function renderItems(){const container=$('#rfq-items');if(!container)return;if(!productData.length){container.innerHTML='<p>Loading product data…</p>';return}container.innerHTML=items.length?items.map((it,i)=>{const p=productData.find(p=>p.id===it.id);return `<fieldset class="rfq-item" data-uid="${escapeHTML(it.uid)}"><legend class="visually-hidden">Enquiry line ${i+1}: ${escapeHTML(p?.name||it.id)}</legend><div class="rfq-item-top"><h3>${escapeHTML(p?.name||it.id)}</h3><button type="button" class="remove-item" data-remove="${escapeHTML(it.uid)}" aria-label="Remove ${escapeHTML(p?.name||it.id)} line ${i+1}">Remove</button></div><div class="form-grid">${['material','grade','standard','size','quantity','notes'].map(k=>`<div class="field"><label for="item-${i}-${k}">${k[0].toUpperCase()+k.slice(1)}${['size','quantity'].includes(k)?' *':''}</label><input id="item-${i}-${k}" data-key="${k}" value="${escapeHTML(it[k])}" ${['size','quantity'].includes(k)?'required':''} maxlength="${k==='notes'?2000:200}" placeholder="${k==='quantity'?'e.g. 20 pieces / 150 metres':''}"></div>`).join('')}</div></fieldset>`}).join(''):'<div class="empty-state"><h3>Your enquiry starts here.</h3><p>Add a product below, or explore the product portfolio.</p><a class="text-link" href="/products/">Browse products</a></div>'}
$('#rfq-items')?.addEventListener('input',e=>{const key=e.target.dataset.key;if(!key)return;const item=items.find(x=>x.uid===e.target.closest('[data-uid]').dataset.uid);if(item){item[key]=e.target.value;persist()}});
$('#rfq-items')?.addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b){items=items.filter(x=>x.uid!==b.dataset.remove);persist();renderItems();$('#add-category').focus();toast('Product removed.')}});
$('#add-item')?.addEventListener('click',()=>{addProduct($('#add-category').value);const last=$$('.rfq-item').at(-1);last?.querySelector('input')?.focus()});
$('#clear-enquiry')?.addEventListener('click',()=>{if(!items.length||confirm('Clear all selected products and technical requirements?')){items=[];try{localStorage.removeItem(storageKey)}catch{}updateCount();renderItems();toast('Enquiry cleared.')}});
$$('.blueprint-toggle').forEach(b=>b.addEventListener('change',()=>b.closest('.product-visual').classList.toggle('show-blueprint',b.checked)));
$('#movement')?.addEventListener('input',e=>$('.joint-demo').style.setProperty('--movement',`${Number(e.target.value)}px`));
$('#pipe-material')?.addEventListener('change',e=>{const texts={'Carbon Steel':'Carbon steel references include ASTM A106, A53, A333, A671, A672, and API 5L.','Stainless Steel':'Published grades include 304/304L, 316/316L, 321, 347, and 904/904L. The last designation requires engineering review.','Duplex Stainless Steel':'Published duplex pipe references include UNS S31803 and S32205.','Super Duplex Stainless Steel':'Published super duplex pipe references include UNS S32750/S32760.','High Alloy Steel':'High alloy pipes are included in the portfolio. Detailed grades require confirmation.'};$('#pipe-material-info').textContent=texts[e.target.value]});
async function initMaterials(){if(!$('.material-options'))return;const materials=await fetchData('materials');function render(i){const m=materials[i],panel=$('#material-panel');panel.setAttribute('aria-labelledby',`material-tab-${i}`);$('.material-swatch').style.filter=`brightness(${.75+i*.045})`;$('#material-copy').innerHTML=`<p class="eyebrow">MATERIAL FAMILY</p><h2>${escapeHTML(m.name)}</h2><p>${escapeHTML(m.overview)}</p><h3>Published grade references</h3><ul class="technical-list">${(m.grades.length?m.grades:['Detailed grades require technical confirmation.']).map(t=>`<li>${escapeHTML(t)}</li>`).join('')}</ul><h3>Technical standards</h3><ul class="technical-list">${(m.standards.length?m.standards:['Project specification and applicable standards to be confirmed.']).map(t=>`<li>${escapeHTML(t)}</li>`).join('')}</ul><h3>Related product categories</h3><div class="chip-list">${m.relatedProducts.length?m.relatedProducts.map(id=>`<a class="chip" href="/products/${id}/">${escapeHTML(id.replaceAll('-',' '))}</a>`).join(''):'<p>No product-to-material mapping is confirmed in the starting dataset.</p>'}</div><a class="button" href="/request-a-quote/?material=${encodeURIComponent(m.name)}">Enquire about ${escapeHTML(m.name)}</a>`}tabs($('.material-options'),render);render(0)}
async function initMarkets(){if(!$('#market-select'))return;const markets=await fetchData('locations');function render(i){const m=markets[i];$('#market-type').textContent=m.type.toUpperCase();$('#market-name').textContent=m.name;$('#market-detail').textContent=i===0?'Dubai · DMCC free zone. Units 2501 & 2502, Jumeirah Business Center 4.':'Geographic business market. A physical branch address has not been supplied.';$('#market-select').value=i;$$('.map-pin').forEach((b,n)=>b.setAttribute('aria-pressed',n===i))}$$('.map-pin').forEach(b=>b.addEventListener('click',()=>render(Number(b.dataset.market))));$('#market-select').addEventListener('change',e=>render(Number(e.target.value)));render(0)}
function initValves(){const data=productData.find(p=>p.id==='valves').sections['Valve families'];let family='',valves=[];for(const line of data.split('\n').map(x=>x.trim()).filter(Boolean)){if(line.startsWith('- '))valves.push({name:line.slice(2),family});else family=line}let active='All';const families=['All',...new Set(valves.map(v=>v.family))];$('#valve-filters').innerHTML=families.map(f=>`<button class="chip ${f==='All'?'active':''}" data-family="${escapeHTML(f)}" aria-pressed="${f==='All'}">${escapeHTML(f)}</button>`).join('');function render(){const q=$('#valve-search').value.trim().toLowerCase();const result=valves.filter(v=>(active==='All'||v.family===active)&&(v.name+' '+v.family).toLowerCase().includes(q));$('#valve-results').innerHTML=result.length?result.map(v=>`<article class="valve-card"><p class="eyebrow">${escapeHTML(v.family)}</p><h3>${escapeHTML(v.name)}</h3><dl><dt>Pressure class / nominal size</dt><dd>To be specified for enquiry</dd><dt>Material / connection / standards</dt><dd>Subject to technical confirmation</dd><dt>Operating temperature</dt><dd>Provide project conditions</dd></dl><button class="button add-product" data-id="valves" data-notes="${escapeHTML(v.name)}">Add to enquiry</button></article>`).join(''):'<p>No matching valve subtype. Try a broader search.</p>'}$('#valve-filters').addEventListener('click',e=>{const b=e.target.closest('[data-family]');if(!b)return;active=b.dataset.family;$$('[data-family]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});render()});$('#valve-search').addEventListener('input',render);render()}
function download(filename,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let config={rfqEndpoint:'',contactEndpoint:'',maxUploadMB:10,legalApproved:false};
async function initForms(){if(!$('#rfq-form')&&!$('#contact-form'))return;config=await fetchData('config');for(const type of ['rfq','contact']){const form=$(`#${type}-form`);if(!form)continue;const endpoint=config[`${type}Endpoint`];if(endpoint&&config.legalApproved){form.querySelector('[type=submit]').textContent=type==='rfq'?'Submit enquiry':'Send message';const notice=$('.draft-banner');notice.textContent='Your enquiry will be sent to the configured United Piping enquiry service.'}form.addEventListener('submit',async e=>{e.preventDefault();const status=$(`#${type}-status`);if(type==='rfq'&&!items.length){status.textContent='Add at least one product before preparing your enquiry.';$('#add-category').focus();return}const doc=$('#documents')?.files[0];if(doc&&(!/\.(pdf|csv|xlsx|docx)$/i.test(doc.name)||doc.size>config.maxUploadMB*1024*1024)){status.textContent='Choose a PDF, CSV, XLSX, or DOCX file up to 10 MB.';return}const data=new FormData(form);if(type==='rfq')data.set('items',JSON.stringify(items));const submit=form.querySelector('[type=submit]');submit.disabled=true;status.textContent=endpoint&&config.legalApproved?'Sending enquiry…':'Preparing your draft…';try{if(endpoint&&config.legalApproved){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),20000);let r;try{r=await fetch(endpoint,{method:'POST',body:data,signal:ctrl.signal,headers:{Accept:'application/json'}})}finally{clearTimeout(timer)}if(!r.ok)throw new Error('The enquiry service could not accept your message. Your entries remain available; please retry or contact us by email.');const result=await r.json();if(result.success!==true||!result.reference)throw new Error('Delivery was not confirmed by the enquiry service. Please contact us before retrying.');status.textContent=`Enquiry received. Reference: ${String(result.reference).slice(0,100)}`;}else{let text='UNITED PIPING SOLUTIONS\n'+(type==='rfq'?'REQUEST FOR QUOTATION':'GENERAL ENQUIRY')+' — DRAFT, NOT SENT\n\n';for(const [k,v] of data.entries()){if(k==='document'||k==='items')continue;text+=`${k}: ${v}\n`}if(type==='rfq'){text+='\nREQUIRED PRODUCTS\n';items.forEach((it,i)=>{text+=`\n${i+1}. ${productData.find(p=>p.id===it.id)?.name||it.id}\n`;for(const k of ['material','grade','standard','size','quantity','notes'])text+=`${k}: ${it[k]||'To be confirmed'}\n`})}if(doc)text+=`\nAttach separately: ${doc.name}\n`;text+='\nSend this draft to info@unitedpipinggroup.com. Technical details and availability require confirmation.\n';download(type==='rfq'?'united-piping-enquiry.txt':'united-piping-message.txt',text);status.textContent='Draft downloaded. It has not been sent. Email the file and any project documents to info@unitedpipinggroup.com.'}}catch(error){status.textContent=error.name==='AbortError'?'The service timed out. Delivery is unconfirmed. Your entries are still available.':error.message}finally{submit.disabled=false}})}}
function animate(){window.initIndustrialMotion?.()}
Promise.allSettled([initProducts(),initMaterials(),initMarkets(),initForms()]).then(results=>{results.forEach(r=>{if(r.status==='rejected'){toast(r.reason.message);console.error(r.reason)}});const requested=new URLSearchParams(location.search).get('material');if(requested&&$('#rfq-items')){toast(`Add a product and specify ${requested} in its material field.`)}animate()});
